function cashState(row={},fallback){const receivable=finite(row.receivableWeight)?row.receivableWeight:0,total=finite(row.cashWeight)?row.cashWeight:fallback,liquid=finite(row.liquidCashWeight)?row.liquidCashWeight:finite(total)?Math.max(0,total-receivable):null;return {liquid,receivable};}
function cashSummary(row){const cash=cashState(row);return `현금 ${fmt(cash.liquid,'pct')}${cash.receivable>0?` · 현금 수취권 ${fmt(cash.receivable,'pct')}`:''}`;}
function meanBuyIC(rows){const values=(rows||[]).map(p=>p.buy).filter(finite);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null;}
function positivePage(value){const number=Number(value);return Number.isSafeInteger(number)&&number>0?number:1;}
function symbolPageData(symbols,query='',requestedPage=1){const all=Array.isArray(symbols)?symbols:[],q=String(query).trim().toUpperCase(),filtered=all.filter(s=>String(s.symbol||s.ticker||s).toUpperCase().includes(q)),pages=Math.max(1,Math.ceil(filtered.length/100)),page=Math.min(pages,positivePage(requestedPage)),offset=(page-1)*100;return {rows:filtered.slice(offset,offset+100),page,pages,total:all.length,count:filtered.length,start:filtered.length?offset+1:0,end:Math.min(offset+100,filtered.length)};}
