function sync(replace=false){const q=new URLSearchParams();Object.entries(state).forEach(([k,v])=>{if(v&&(!Array.isArray(v)||v.length)&&!(k==='symbolPage'&&v===1))q.set(k==='search'?'q':k,Array.isArray(v)?v.join(','):v);});history[replace?'replaceState':'pushState'](null,'',`${location.pathname}?${q}`);}
function metric(m,k){return m?.[k]??({max_drawdown:m?.mdd??m?.maxDrawdown,annual_return:m?.cagr,sortino:m?.sortino_ratio}[k]);}
const metricNames={cagr:'CAGR',sortino:'Sortino',calmar:'Calmar',max_drawdown:'MDD',sharpe:'Sharpe',stability:'기간 안정성'};
function metricText(row,k){const key=k==='max_drawdown'?'mdd':k;const status=row?.metricStates?.[key];return status==='positive_infinity'?'∞':status==='negative_infinity'?'−∞':fmt(metric(row?.metrics,k),['cagr','max_drawdown','stability'].includes(k)?'pct':'number');}
function metrics(m,states={}){return '<div class="lab-metrics">'+Object.entries(metricNames).map(([k,l])=>`<span>${l}<strong>${metricText({metrics:m,metricStates:states},k)}</strong></span>`).join('')+'</div>';}
function panel(title,body,extra=''){return `<section class="lab-panel"><div class="lab-section-heading"><h2>${escape(title)}</h2>${extra}</div>${body}</section>`;}
function table(head,rows){return `<div class="lab-table-scroll"><table class="lab-table"><thead><tr>${head.map(h=>`<th scope="col" class="${/^(비중|점수|CAGR|Sortino|Calmar|MDD|회전율|비용|순위 상관|수익 상관|비중 중복)$/.test(h)?'numeric':''}">${escape(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${head.length}" class="empty">표시할 결과가 없습니다.</td></tr>`}</tbody></table></div>`;}
function holdings(rows){
  rows=sortedHoldings(rows);const hasScore=rows.some(h=>finite(h.score)),max=Math.max(0,...rows.map(h=>finite(h.weight)?h.weight:0)),size=10,groups=[];
  for(let offset=0;offset<rows.length;offset+=size){const page=rows.slice(offset,offset+size);groups.push(`<div class="lab-holdings-group" data-holdings-group="${offset/size}">${table(['순위','종목','비중',...(hasScore?['점수']:[])],page.map((h,i)=>`<tr><td class="lab-rank">${offset+i+1}</td><td class="lab-symbol">${escape(h.symbol||h.ticker)}</td><td class="numeric lab-weight"><span class="lab-weight-track" aria-hidden="true"><i style="width:${finite(h.weight)&&max?Math.max(0,h.weight/max*100):0}%"></i></span><span>${fmt(h.weight,'pct')}</span></td>${hasScore?`<td class="numeric">${fmt(h.score,'score')}</td>`:''}</tr>`))}</div>`);}
  if(!groups.length)return '<div class="lab-empty">보유 주식이 없습니다.</div>';
  return `<div class="lab-holdings" data-holdings-page="0" data-holdings-count="${rows.length}"><div class="lab-holdings-grid">${groups.join('')}</div>${groups.length>1?`<div class="lab-holdings-pagination"><span data-holdings-range role="status">1–${Math.min(size,rows.length)} / ${rows.length}종목</span><div><button type="button" class="lab-button secondary" data-holdings-step="-1" disabled>이전</button><button type="button" class="lab-button secondary" data-holdings-step="1">다음</button></div></div>`:''}</div>`;
}
function bindHoldings(){document.querySelectorAll('#view-'+state.view+' [data-holdings-step]').forEach(button=>{button.onclick=()=>{const box=button.closest('.lab-holdings'),count=+box.dataset.holdingsCount,pages=Math.ceil(count/10),page=Math.max(0,Math.min(pages-1,+box.dataset.holdingsPage+(+button.dataset.holdingsStep)));box.dataset.holdingsPage=String(page);box.querySelectorAll('[data-holdings-group]').forEach(group=>group.dataset.mobileHidden=String(+group.dataset.holdingsGroup!==page));box.querySelector('[data-holdings-range]').textContent=`${page*10+1}–${Math.min(count,(page+1)*10)} / ${count}종목`;box.querySelector('[data-holdings-step="-1"]').disabled=page===0;box.querySelector('[data-holdings-step="1"]').disabled=page===pages-1;const replacement=box.querySelector(`[data-holdings-step="${button.dataset.holdingsStep}"]`);if(!replacement.disabled)replacement.focus();};});}
function sortedCandidates(rows){return [...(rows||[])].sort((a,b)=>{const eligible=x=>['eligible','selected'].includes(x.status);return Number(eligible(b))-Number(eligible(a))||(finite(b.score)?b.score:-Infinity)-(finite(a.score)?a.score:-Infinity)||a.id.localeCompare(b.id);});}
function historyPanel(hist,fixed=false){const visible=hist.slice().reverse().slice(0,showAllHistory?hist.length:12);return panel(fixed?'리밸런싱 이력':'월별 교체 이력',table(['신호일',...(fixed?[]:['선택','점수']),'체결일','회전율','비용','상태'],visible.map(h=>`<tr><td>${fixed?escape(h.date):`<button class="lab-text-button" data-month="${escape(h.date)}">${escape(h.date)}</button>`}</td>${fixed?'':`<td>${escape(h.label||result.factors.find(f=>f.id===h.factorId)?.label||'현금')}</td><td>${fmt(h.score,'score')}</td>`}<td>${escape(h.executionDate||'—')}</td><td>${fmt(h.turnover,'pct')}</td><td>${fmt(h.cost,'pct')}</td><td>${escape(executionLabel(h))}</td></tr>`)),hist.length>12?`<button type="button" class="lab-text-button" id="toggle-history" aria-expanded="${showAllHistory}">${showAllHistory?'최근 12개월':`전체 ${hist.length}개월 보기`}</button>`:'');}

function chart(series,{kind='pct',compact=false,title='성과',normalize=false}={}){if(normalize)series=commonSeries(series);series=series.filter(s=>s.points?.length);if(!series.length)return '<div class="lab-empty">계산 가능한 시계열이 없습니다.</div>';const id=`chart-${++chartSerial}`;charts.push({id,series,kind,compact,title});return `<div id="${id}" class="lab-chart-wrap"><div class="lab-legend">${series.map((s,i)=>`<button type="button" data-series="${i}" aria-pressed="true"><span class="lab-swatch" style="--series-color:${palette[i%palette.length]}"></span>${escape(s.label)}</button>`).join('')}</div><svg class="lab-chart ${compact?'compact':''}" role="img" aria-label="${escape(title)}. 좌우 화살표로 날짜 탐색" tabindex="0" viewBox="0 0 900 ${compact?170:300}"></svg><div class="lab-chart-values" aria-live="polite"></div></div>`;}
