function isResearch(f){return f.definition?.selectionEligible===false||f.definition?.researchOnly||f.definition?.research_only||f.direction===0||f.direction==='research'||f.selectionEligible===false;}
function explore(){const families=[...new Set(result.factors.map(f=>f.family))].filter(Boolean);html('#family-filter','<option value="">전체 계열</option>'+families.map(f=>`<option value="${escape(f)}">${escape(familyLabel(f))}</option>`).join(''));$('#family-filter').value=state.family;$('#factor-search').value=state.search;$('#status-filter').value=state.status;$('#factor-sort').value=state.sort;let fs=result.factors.filter(f=>(!state.search||`${f.id} ${f.label} ${f.family} ${f.definition?.hypothesis||''}`.toLowerCase().includes(state.search.toLowerCase()))&&(!state.family||f.family===state.family)&&(!state.status||(state.status==='research'?isResearch(f):state.status==='candidate'?!isResearch(f):state.status==='available'?f.status==='available'||f.status==='ready':f.status!=='available'&&f.status!=='ready')));if(state.sort!=='catalog')fs.sort((a,b)=>{let x=state.sort==='score'?result.selection.current?.candidates?.find(c=>c.id===a.id)?.score:state.sort==='ic'?meanBuyIC(a.ic):metric(a.metrics,state.sort);let y=state.sort==='score'?result.selection.current?.candidates?.find(c=>c.id===b.id)?.score:state.sort==='ic'?meanBuyIC(b.ic):metric(b.metrics,state.sort);return (finite(y)?y:-Infinity)-(finite(x)?x:-Infinity)||a.id.localeCompare(b.id);});html('#explore-summary',`${fs.length} / ${result.factors.length}개 정의`);html('#factor-table',table(['비교','팩터','계열','상태','CAGR','Sortino','Calmar','MDD'],fs.map(f=>`<tr class="${f.id===state.factor?'selected':''}"><td><input type="checkbox" data-compare="${escape(f.id)}" aria-label="${escape(f.label)} 비교" ${state.compare.includes(f.id)?'checked':''}></td><td class="name"><button class="lab-text-button" data-factor="${escape(f.id)}">${escape(f.label)}</button><small>${escape(f.id)}${isResearch(f)?' · 연구 전용':''}</small></td><td>${escape(familyLabel(f.family))}</td><td>${escape(labelStatus(f.status))}</td>${['cagr','sortino','calmar','max_drawdown'].map(k=>`<td class="numeric">${metricText(f,k)}</td>`).join('')}</tr>`)));detail();}
function detail(){const f=result.factors.find(f=>f.id===state.factor);$('#factor-detail').hidden=!f;if(!f)return;const tabs={performance:'성과',relation:'IC·분위',holdings:'구성',definition:'정의·검증'};let body='';if(state.detail==='performance')body=(f.status==='partial_data'?`<p class="lab-caption">일부 기간 미확정 · 최종 평가일 ${escape(f.lastValuedDate||'—')}${finite(f.valuationCoverage)?` · 관측 ${fmt(f.valuationCoverage,'pct')}`:''}</p>`:'')+metrics(f.metrics,f.metricStates)+riskNote(f)+chart([{label:f.label,points:f.nav}],{normalize:true})+chart([{label:f.label,points:f.drawdown}],{compact:true,title:'낙폭'});else if(state.detail==='relation')body=chart(['raw','buy'].map(k=>({label:k==='raw'?'원점수 IC':'매수 방향 IC',points:(f.ic||[]).map(p=>({date:p.date,value:p[k]}))})),{kind:'number',title:'월별 IC'})+chart([1,2,3,4,5].map(k=>({label:`${k}분위`,points:(f.quintiles||[]).map(p=>({date:p.date,value:p[`q${k}`]}))})),{title:'다음 보유기간 동일비중 수익'})+'<p class="lab-caption">분위별 동일비중 · 비용 전 수익</p>';else if(state.detail==='holdings')body=`<p class="lab-caption">${cashSummary(f)}</p>`+holdings(f.holdings);else body='<dl class="lab-definition">'+Object.entries(f.definition||{}).filter(([k])=>!['id','label','name'].includes(k)).map(([k,v])=>`<dt>${escape(definitionLabel(k))}</dt><dd>${definitionValue(k,v)}</dd>`).join('')+'</dl>';body+=state.detail==='definition'?researchDetails(f.id):'';html('#factor-detail',panel(f.label,`<div class="lab-detail-tabs" role="tablist">${Object.entries(tabs).map(([k,v])=>`<button role="tab" aria-selected="${state.detail===k}" data-detail="${k}">${v}</button>`).join('')}</div>${body}`,`<button class="lab-button secondary" data-copy="${escape(f.id)}">${f.definition?.sourceProject?'실험 설정 복사':'관련 변형 실험'}</button>`));}
function researchDetails(id){const r=result.research||{};const boot=(r.bootstrap||[]).find(b=>b.blockSessions===20);const b=boot?.results?.find(b=>b.id===id);let out=panel('불확실성',b?table(['추정 대상','평균','95% 하한','95% 상한','Holm p'],[`<tr><td>SPY 대비 일평균 수익</td><td>${fmt(b.estimate,'pct')}</td><td>${fmt(b.lower,'pct')}</td><td>${fmt(b.upper,'pct')}</td><td>${fmt(b.holm)}</td></tr>`])+`<p class="lab-caption">동일 날짜 블록 ${boot.blockSessions}세션 · ${boot.repetitions.toLocaleString()}회 재표집</p>`:'<p class="lab-caption">추정 가능한 표본이 없습니다.</p>');const regimes=Object.entries(r.regimes||{}).filter(([,v])=>v[id]);out+=panel('시장 국면',table(['구간','관측일','일평균 수익'],regimes.map(([k,v])=>`<tr><td>${escape({up:'상승',down:'하락',high_vol:'고변동',low_vol:'저변동',crash_rebound:'급락 후 반등'}[k]||k)}</td><td>${fmt(v[id].observations)}</td><td>${fmt(v[id].meanDailyReturn,'pct')}</td></tr>`)));const exposure=(r.conditionalExposures||[]).find(x=>x.id===id);if(exposure)out+=panel('조건부 노출',table(['비교 팩터','노출'],Object.entries(exposure.exposures||{}).map(([k,v])=>`<tr><td>${escape(k)}</td><td>${fmt(v)}</td></tr>`))+`<p class="lab-caption">${fmt(exposure.observations)}거래일 · 설명력 ${fmt(exposure.rSquared,'pct')}</p>`);return out;}
function compareResearch(ids){const r=result.research||{};return panel('전체 연구기간 신호·수익·보유 중복',table(['정의 A','정의 B','순위 상관','수익 상관','비중 중복'],(r.correlations||[]).filter(x=>ids.includes(x.left)&&ids.includes(x.right)).map(x=>`<tr><td>${escape(x.left)}</td><td>${escape(x.right)}</td><td>${fmt(x.signal)}</td><td>${fmt(x.returns)}</td><td>${fmt((r.overlap||[]).find(o=>o.left===x.left&&o.right===x.right)?.value,'pct')}</td></tr>`)));}
function compare(){const fs=state.compare.map(id=>result.factors.find(f=>f.id===id)).filter(Boolean),period=commonPeriodComparison(fs.map(f=>({id:f.id,label:f.label,points:f.nav})));html('#compare-count',fs.length?`(${fs.length})`:'');let body='';if(!fs.length)body='<div class="lab-empty">탐색에서 비교할 팩터를 선택하세요.</div>';else if(!period)body='<div class="lab-empty">비교 가능한 공통 평가기간이 없습니다.</div>';else{const rows=period.series;body=`<p class="lab-caption" id="comparison-period">${escape(period.start)}–${escape(period.end)} · ${period.sessions.toLocaleString()}거래일${fs.length>4?' · 차트는 처음 4개 정의':''}</p>`+panel('같은 기간 성과',chart(rows.slice(0,4))+chart(rows.slice(0,4).map(s=>({label:s.label,points:s.drawdown})),{compact:true,title:'같은 기간 낙폭'}))+panel('같은 기간 지표',table(['팩터','CAGR','Sortino','Calmar','MDD','평가'],rows.map(s=>`<tr><td>${escape(s.label)}</td>${['cagr','sortino','calmar','max_drawdown'].map(k=>`<td class="numeric">${metricText(s,k)}</td>`).join('')}<td>${!s.endingNavAvailable?'끝점 미확정':s.missingNavSessions?'가격 공백 포함':s.dailyRiskObservations<2?'일별 표본 부족':'확정'}</td></tr>`)))+(rows.some(s=>s.missingNavSessions)?'<p class="lab-caption">가격 공백은 유지하며, 일별 위험지표는 연속 관측 구간에서 계산합니다.</p>':'');}html('#compare-content',`<div class="lab-section-heading"><h2>팩터 비교</h2><div class="lab-actions"><button class="lab-button secondary" id="common-compare" ${fs.length<2||runtime.status!=='available'?'disabled':''} ${runtime.status!=='available'?'title="계산 서버 연결 시 사용 가능"':''}>공통 종목으로 재계산</button><button class="lab-button secondary" data-go="explore">팩터 추가</button></div></div><div class="lab-chips">${fs.map(f=>`<button class="lab-chip" data-remove="${escape(f.id)}">${escape(f.label)} ×</button>`).join('')}</div>${body}`);if(fs.length>1)$('#compare-content').insertAdjacentHTML('beforeend',compareResearch(state.compare));$('#common-compare').onclick=()=>startRun({settings:result.settings,comparisonFactors:state.compare,commonUniverse:true,hypothesis:'날짜별 공통 적격 종목에서 팩터 비교'});}
function dataView(){const d=result.data;html('#data-content',auditNotice(result.audit)+panel('입력 데이터',`<dl class="lab-definition">${Object.entries(d).filter(([k,v])=>v===null||typeof v!=='object').map(([k,v])=>`<dt>${escape(({asOf:'관측 기준일',requestedCount:'요청 종목',pricedCount:'가격 보유(벤치마크 포함)',eligibleCount:'투자 적격',snapshotId:'입력 스냅샷'})[k]||k)}</dt><dd>${escape(v??'—')}</dd>`).join('')}</dl>`)+panel('실행 정보',`<dl class="lab-definition">${Object.entries({...result.resultIdentity,...result.settings}).map(([k,v])=>`<dt>${escape(k)}</dt><dd>${escape(v==null?'—':typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>`)+panel('종목별 자료','<label class="lab-inline-control">종목 검색 <input id="symbol-query" type="search" placeholder="Ticker"></label><div id="symbol-results"></div><nav id="symbol-pagination" class="lab-pagination" aria-label="종목 자료 페이지"></nav>')+panel('계산 기준','<p>월말 신호 · 다음 거래일 종가 체결 · 비용 후 일별 NAV. 선택 평가는 최근 756거래일의 CAGR 25%, Sortino 25%, Calmar 20%, MDD 20%, 기간 안정성 10%를 사용합니다.</p><p class="lab-caption">무료 데이터 · 생존 편향 미보정 · 현금 및 기준수익률 0%. 자료 부족은 0과 구분합니다.</p>'));const symbols=d.symbols||d.universe||d.requestedSymbols||[];let searchEditing=false;$('#symbol-query').value=state.symbol;function show(){const page=symbolPageData(symbols,state.symbol,state.symbolPage),urlPage=new URLSearchParams(location.search).get('symbolPage');if(state.symbolPage!==page.page||(urlPage&&urlPage!==String(page.page))){state.symbolPage=page.page;sync(true);}html('#symbol-results',table(['종목','출처','관측일','기본 수집시각','상태','제외 사유'],page.rows.map(s=>`<tr><td>${escape(s.symbol||s.ticker||s)}</td><td>${escape(s.source||s.provider||'—')}</td><td>${escape(s.observedAt||s.lastObservation||'—')}</td><td>${escape(s.collectedAt||s.retrievedAt||'—')}</td><td>${escape(labelStatus(s.status))}</td><td>${escape(reasonLabel(s.reason||s.exclusionReasons))}</td></tr>`)));html('#symbol-pagination',`<span id="symbol-count" class="lab-caption" role="status">${page.count?`${page.start.toLocaleString()}–${page.end.toLocaleString()}`:'0'} / ${page.count.toLocaleString()}종목${page.count!==page.total?` · 전체 ${page.total.toLocaleString()}종목`:''}</span><div class="lab-actions"><button id="symbol-prev" class="lab-button secondary" type="button" ${page.page===1?'disabled':''}>이전</button><span class="lab-caption">${page.page} / ${page.pages}페이지</span><button id="symbol-next" class="lab-button secondary" type="button" ${page.page===page.pages?'disabled':''}>다음</button></div>`);for(const [id,step] of [['symbol-prev',-1],['symbol-next',1]])$('#'+id).onclick=()=>{searchEditing=false;state.symbolPage=Math.max(1,Math.min(page.pages,state.symbolPage+step));sync();show();const button=$('#'+id);if(!button.disabled)button.focus();};}$('#symbol-query').oninput=e=>{state.symbol=e.target.value;state.symbolPage=1;sync(searchEditing);searchEditing=true;show();};$('#symbol-query').onblur=()=>{searchEditing=false;};show();}
function validLegacy(rows){return (rows||[]).filter(r=>['parameter_experiment','composite_experiment'].includes(r.status)&&!r.original?.requires_fundamentals?.length);}
function legacyOptions(){const select=$('#legacy-definition'),previous=select.value||(result?.resultIdentity?.strategyType==='fixed_factor_experiment'?`${result.factors[0]?.definition?.sourceProject}:${result.factors[0]?.definition?.sourceId}`:''),q=$('#legacy-search').value.toLowerCase();const rows=legacyDefinitions.filter(r=>(!copiedFactor||(copiedFactor.project?r.project===copiedFactor.project&&r.legacyId===copiedFactor.legacyId:r.canonicalId===copiedFactor.id))&&`${r.legacyId} ${r.original?.category||''} ${r.original?.description||''}`.toLowerCase().includes(q));select.innerHTML='<option value="">'+(rows.length?'실행할 정의 선택':'실행 가능한 관련 변형 없음')+'</option>'+['momentum','best'].map(project=>`<optgroup label="${project==='best'?'Best':'Momentum'}">${rows.filter(r=>r.project===project).map(r=>`<option value="${escape(r.project+':'+r.legacyId)}">${escape(r.legacyId)}</option>`).join('')}</optgroup>`).join('');select.value=rows.some(r=>r.project+':'+r.legacyId===previous)?previous:'';legacyDescription();updateExperimentTarget();}
function updateExperimentTarget(){const note=$('#experiment-target');note.hidden=!copiedFactor;note.textContent=copiedFactor?copiedFactor.project?`실행 정의 ${copiedFactor.project}:${copiedFactor.legacyId}`:`기준 정의 ${copiedFactor.label} · 실행할 관련 변형을 선택하세요.`:'';}
function copyFactorToExperiment(id){const f=result.factors.find(f=>f.id===id);if(!f)return;resetForm();copiedFactor={id:f.id,label:f.label,project:f.definition?.sourceProject,legacyId:f.definition?.sourceId};$('#experiment-mode').value='legacy';$('#legacy-fields').hidden=false;$('#legacy-search').value='';$('#legacy-definition').value='';legacyOptions();if(copiedFactor.project){$('#legacy-definition').value=`${copiedFactor.project}:${copiedFactor.legacyId}`;legacyDescription();}$('#experiment-form').elements.hypothesis.value=`${f.label} 설정 민감도`;state.view='experiments';}
function chosenLegacy(){const key=$('#legacy-definition').value;return legacyDefinitions.find(r=>r.project+':'+r.legacyId===key);}
function legacyDescription(){const row=chosenLegacy(),d=row?.original||{};$('#legacy-description').textContent=row?[d.formula||d.description,(d.params||[]).map(([k,v])=>`${k}=${v}`).join(' · ')].filter(Boolean).join(' · '):'정의를 선택하세요.';}
function fixedCurrent(){const sel=result.selection,def=result.experimentDefinition||result.factors[0]?.definition||{},factor=result.factors[0],label=def.label||def.name||factor?.label||sel.current?.label||'실험';html('#current-content',`<div class="lab-section-heading"><h2>실험 포트폴리오</h2><span class="lab-caption">${escape(label)} · ${escape(valuationLabel(sel))}</span></div>${panel(label,metrics(sel.metrics,sel.metricStates)+chart([{label,points:sel.nav},...(result.comparisons||[]).filter(r=>r.id==='SPY').map(r=>({label:r.label,points:r.nav}))],{normalize:true})+chart([{label,points:sel.drawdown}],{compact:true,title:'실험 낙폭'}))}${panel('모형 보유',`<p class="lab-caption">${cashSummary(sel)}</p>`+holdings(sel.holdings))}${sel.history.length?historyPanel(sel.history,true):''}`);const toggle=$('#toggle-history');if(toggle)toggle.onclick=()=>{showAllHistory=!showAllHistory;render();};}
function updateRuntime(){const enabled=runtime.status==='available';const fields=$('#experiment-fields');if(fields)fields.disabled=!enabled;const note=$('#experiment-runtime');if(note){note.hidden=enabled;note.textContent=runtime.status==='checking'?'계산 서버 확인 중':runtime.status==='static'?'저장된 결과 조회 · 새 실험은 로컬 계산 서버에서 실행할 수 있습니다.':'계산 서버에 연결하지 못했습니다. 저장된 결과를 표시합니다.';}}
function experimentView(){updateRuntime();html('#experiment-source',`기준 실행 ${escape(result.resultIdentity?.resultId||'—')} · ${escape(result.data.asOf||'—')}`);renderJobs();html('#experiment-stress','');const stress=result.research?.stress||[];if(stress.length)html('#experiment-stress',panel('실행 스트레스','<p class="lab-caption">선택 고정 조건 외에는 매월 후보를 다시 평가합니다.</p>'+table(['설정','평가 기간','CAGR','Sortino','MDD'],stress.map(s=>`<tr><td>${escape(stressLabel(s))}</td><td>${escape(s.nav?.[0]?.date||'—')}<br>${escape(s.nav?.at(-1)?.date||'—')}</td><td>${fmt(s.metrics?.cagr,'pct')}</td><td>${fmt(s.metrics?.sortino)}</td><td>${fmt(s.metrics?.mdd,'pct')}</td></tr>`))));}
function renderJobs(){html('#experiment-jobs',(!jobs.length&&runtime.status==='static'?'<p class="lab-caption">이 결과에 포함된 검증 실험</p>':'')+table(['실행','상태','결과'],jobs.map(j=>`<tr><td>${escape(j.runId||j.id)}</td><td>${escape(labelStatus(j.status))}${j.error?`<small>${escape(typeof j.error==='string'?j.error:JSON.stringify(j.error))}</small>`:''}</td><td>${j.status==='completed'?`<button class="lab-text-button" data-job="${escape(j.runId||j.id)}">결과 열기</button>`:'—'}</td></tr>`)));}
function render(){if(!result)return;charts=[];document.querySelectorAll('[data-view]').forEach(e=>{e.setAttribute('aria-current',e.dataset.view===state.view?'page':'false');});VIEWS.forEach(v=>$('#view-'+v).hidden=v!==state.view);$('#data-date').textContent=result.data.asOf||'—';$('#result-state').textContent=valuationState(result.selection).pending?'평가 보류':executionLabel(result.selection.current);$('#compare-count').textContent=state.compare.length?`(${state.compare.length})`:'';({current:result.resultIdentity?.strategyType==='fixed_factor_experiment'?fixedCurrent:current,explore,compare,experiments:experimentView,data:dataView,factor:singleFactor}[state.view])();bindHoldings();bindCharts();}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function request(url,options){const r=await fetch(url,options);const body=await r.json().catch(()=>null);if(!r.ok)throw Error(body?.error?.message||body?.error||`요청 실패 (${r.status})`);if(!body||typeof body!=='object')throw Error('응답 형식이 맞지 않습니다.');return body;}
async function loadRuntime(){if(!isLocalHost(location.hostname)){updateRuntime();return;}const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),4000);try{const p=await request(runtime.apiBase+'/runs',{signal:controller.signal});if(!runtimeAccess(location.hostname,p))throw Error('실행 목록 형식이 맞지 않습니다.');jobs=p.runs;runtime.status='available';updateRuntime();if(state.view==='experiments'||state.view==='compare')render();jobs.filter(j=>['queued','running','validating'].includes(j.status)).forEach(j=>getJob(j.runId||j.id).catch(e=>message(e.message,true)));}catch(_){runtime.status='offline';updateRuntime();if(state.view==='experiments'||state.view==='compare')render();}finally{clearTimeout(timeout);}}
async function fetchRunResult(id,job){if(!/^[a-f0-9]{32}$/.test(id))throw Error('실험 실행 ID를 확인하세요.');if(runtime.status!=='available'||!isLocalHost(location.hostname))throw Error('실험 결과는 로컬 계산 서버에서 조회할 수 있습니다.');if(runResults.has(id))return runResults.get(id);const j=job||await request(runtime.apiBase+'/runs/'+encodeURIComponent(id));if(j.status!=='completed')throw Error(j.status==='failed'?'실패한 실험입니다.':j.status==='queued'||j.status==='running'||j.status==='validating'?'아직 계산 중인 실험입니다.':'실험 상태를 확인하세요.');let p=j.result;if(!p&&j.resultUrl){const u=new URL(j.resultUrl,location.href);if(u.origin!==location.origin)throw Error('결과 주소를 확인하세요.');p=await request(u.href);}p=validate(p);runResults.set(id,p);return p;}
async function restoreLocationResult(){const token=++resultNavigation;state=readState(location.search);if(!state.run){result=baseResult;resetForm();render();message('');return;}try{message('실험 결과를 불러오고 있습니다.');const p=await fetchRunResult(state.run);if(token!==resultNavigation)return;result=p;resetForm();render();message('');}catch(e){if(token!==resultNavigation)return;result=baseResult;resetForm();render();message(`${e.message} 저장된 기본 결과를 표시합니다.`,true);}}
async function getJob(id,open=false){const j=await request(runtime.apiBase+'/runs/'+encodeURIComponent(id));const i=jobs.findIndex(x=>(x.runId||x.id)===id);if(i<0)jobs.unshift({...j,runId:id});else jobs[i]={...jobs[i],...j};renderJobs();if(j.status==='completed'){polls.delete(id);if(open){const token=++resultNavigation,p=await fetchRunResult(id,j);if(token!==resultNavigation)return;result=p;resetForm();state.run=id;state.view='current';state.month='';sync();render();message('실험 결과를 열었습니다.');}return;}if(j.status==='failed'){polls.delete(id);message(typeof j.error==='string'?j.error:'계산에 실패했습니다. 이전 결과를 유지합니다.',true);return;}if(!polls.has(id))polls.set(id,setTimeout(()=>{polls.delete(id);getJob(id).catch(e=>message(e.message,true));},4000));}
async function startRun(body){if(runtime.status!=='available'){updateRuntime();return;}try{message('실험을 요청했습니다.');const j=await request(runtime.apiBase+'/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!j.runId)throw Error('실행 ID가 없습니다.');jobs.unshift(j);state.view='experiments';sync();render();await getJob(j.runId);}catch(e){message(e.message,true);}}
function draft(){const f=$('#experiment-form'),value=k=>f.elements.namedItem(k).value;return {...result.settings,top_n:+value('top_n'),max_weight:+value('max_weight')/100,transaction_cost_bps:+value('transaction_cost_bps'),slippage_bps:+value('slippage_bps'),execution_delay_sessions:1+(+value('execution_delay_sessions')),weighting:value('weighting')};}
function resetForm(){if(!result)return;copiedFactor=null;updateExperimentTarget();const fixed=result.resultIdentity?.strategyType==='fixed_factor_experiment';$('#experiment-mode').value=fixed?'legacy':'monthly';$('#legacy-fields').hidden=!fixed;if(fixed&&legacyDefinitions.length){$('#legacy-definition').value=`${result.factors[0]?.definition?.sourceProject}:${result.factors[0]?.definition?.sourceId}`;legacyDescription();}const f=$('#experiment-form');['top_n','transaction_cost_bps','slippage_bps','execution_delay_sessions','weighting'].forEach(k=>{if(result.settings?.[k]!=null)f.elements[k].value=k==='execution_delay_sessions'?Math.max(0,result.settings[k]-1):result.settings[k];});if(result.settings?.max_weight!=null)f.elements.max_weight.value=result.settings.max_weight*100;updateDiff();}
function updateDiff(){if(!result)return;const d=draft();html('#experiment-diff',Object.keys(d).filter(k=>JSON.stringify(d[k])!==JSON.stringify(result.settings?.[k])).map(k=>`${escape(k)}: ${escape(result.settings?.[k]??'—')} → ${escape(d[k])}`).join(' · ')||'기준 실행과 같은 설정');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-factor],[data-detail],[data-remove],[data-go],[data-month],[data-copy],[data-job]');if(!b)return;e.preventDefault();if(b.dataset.view)state.view=b.dataset.view;if(b.dataset.go)state.view=b.dataset.go;if(b.dataset.factor){state.factor=b.dataset.factor;state.detail='performance';}if(b.dataset.detail)state.detail=b.dataset.detail;if(b.dataset.remove)state.compare=state.compare.filter(x=>x!==b.dataset.remove);if(b.dataset.month){state.month=b.dataset.month;}if(b.dataset.copy)copyFactorToExperiment(b.dataset.copy);if(b.dataset.job){getJob(b.dataset.job,true).catch(e=>message(e.message,true));return;}sync();render();});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=e.target.dataset.compare;state.compare=e.target.checked?[...new Set([...state.compare,id])]:state.compare.filter(x=>x!==id);sync(true);$('#compare-count').textContent=`(${state.compare.length})`;}});
[['#factor-search','search','input'],['#family-filter','family','change'],['#status-filter','status','change'],['#factor-sort','sort','change']].forEach(([s,k,event])=>$(s).addEventListener(event,e=>{state[k]=e.target.value;sync(true);charts=[];explore();bindHoldings();bindCharts();if(k==='search'){$(s).focus();$(s).setSelectionRange(state.search.length,state.search.length);}}));
function themeButton(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').setAttribute('aria-label',dark?'라이트 모드로 전환':'다크 모드로 전환');$('#theme-toggle').setAttribute('aria-pressed',String(dark));}themeButton();
$('#theme-toggle').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('quant-research-theme',t);}catch(_){}themeButton();};
$('#export-result').onclick=()=>result&&download('integrated-result.json',JSON.stringify(result,null,2),'application/json');
$('#export-factors').onclick=()=>download('factors.csv','\ufeff'+csv([['runId','start_date','dataAsOf','transaction_cost_bps','slippage_bps','id','name','status','CAGR','Sortino','Calmar','MDD'],...result.factors.map(f=>[result.resultIdentity?.resultId,result.settings?.start_date,result.data.asOf,result.settings?.transaction_cost_bps,result.settings?.slippage_bps,f.id,f.label,f.status,...['cagr','sortino','calmar','max_drawdown'].map(k=>metric(f.metrics,k))])]),'text/csv;charset=utf-8');
$('#experiment-form').onsubmit=e=>{e.preventDefault();const selected=chosenLegacy();if($('#experiment-mode').value==='legacy'&&!selected){message('실행할 기존 정의를 선택하세요.',true);return;}startRun({settings:draft(),comparisonFactors:state.compare,commonUniverse:false,hypothesis:new FormData(e.target).get('hypothesis'),...($('#experiment-mode').value==='legacy'?{experimentDefinition:{project:selected.project,id:selected.legacyId}}:{})});};$('#experiment-mode').onchange=()=>{copiedFactor=null;updateExperimentTarget();$('#legacy-fields').hidden=$('#experiment-mode').value!=='legacy';legacyOptions();};$('#legacy-search').oninput=legacyOptions;$('#legacy-definition').onchange=legacyDescription;$('#experiment-form').oninput=updateDiff;$('#reset-experiment').onclick=resetForm;

window.addEventListener('popstate',()=>{restoreLocationResult().catch(e=>message(e.message,true));});
request('data/legacy-definitions.json').then(p=>{legacyDefinitions=validLegacy(p.rows);legacyOptions();}).catch(()=>{$('#legacy-description').textContent='기존 정의 목록을 불러오지 못했습니다.';});
updateRuntime();
request('data/integrated-result.json').then(async p=>{baseResult=result=validate(p);resetForm();render();message('');await loadRuntime();await restoreLocationResult();}).catch(e=>message(`결과를 불러오지 못했습니다. ${e.message}`,true));
